STORY = [('hyejoo', '안 그래도 전화하려고 나왔는데.', 'I actually just stepped out to call you.', [(969, '안 그래도 전화하려고 나왔는데')], ''), ('hyejoo', '안에 시장통이야. 우리 따로 나가요.', "Inside is chaotic like a marketplace. Let's slip out separately.", [(970, '안에 시장통이야 우리 따로 나가요')], ''), ('joonmo', '혜주야, 나 너한테 할 말 있다.', 'Hye-joo, I have something to say to you.', [(971, '혜주야 나 너한테 할 말 있다')], ''), ('hyejoo', '네? 무슨 말이요?', 'Yes? What is it?', [(972, '네? 무슨')], 'Completes natural polite question 말이요.'), ('joonmo', '아니다 싶으면 확실하게 얘기해야지.', "When something doesn't feel right, a person should say so clearly.", [(973, '아니다 싶으면 확실하게 얘기해서')], "Adapts Ye-jin's advice into a standalone statement."), ('joonmo', '이별에도 예의라는 게 있는 법이야.', 'Even in a breakup, there is such a thing as courtesy.', [(974, '이별에도 예의라는 게 있는 법이에요')], "Uses casual 이야 matching Joon-mo's voice."), ('joonmo', '네가 좋고 이쁘긴 한데.', "You're nice and pretty, though.", [(975, '네가 좋고 이쁘긴 한데')], ''), ('joonmo', '우리는 네가 원하는 관계가 될 순 없을 것 같아.', "I don't think we can become the kind of relationship you want.", [(976, '네가 원하는'), (976, '관계가 될 순 없을 것 같아')], ''), ('hyejoo', '네?', 'Pardon?', [(977, '네?')], ''), ('joonmo', '따로 만나는 거 그만하자.', "Let's stop meeting on our own.", [(978, '따로 만나는 거 그만하자')], ''), ('joonmo', '미안하다.', "I'm sorry.", [(979, '미안하다')], ''), ('hyejoo', '알겠어요, 선배.', 'I understand, senior.', [], 'Adds calm closing acknowledgment for round-off.')]

